begin;
create extension if not exists pgtap with schema extensions;
select extensions.no_plan();
insert into auth.users(id) select ('4b000000-0000-4000-8000-00000000000'||n)::uuid from generate_series(1,6)n;
insert into auth.mfa_factors(id,user_id,factor_type,status,created_at,updated_at) select id,id,'totp','verified',now(),now() from auth.users where id::text like '4b000000-%';
insert into auth.sessions(id,user_id,factor_id,aal) select id,id,id,'aal2' from auth.users where id::text like '4b000000-%';
insert into public.team_profiles(id,full_name,is_active) select id,'Synthetic project staff',id::text not like '%5' from auth.users where id::text like '4b000000-%';
insert into public.team_role_assignments select ('4b000000-0000-4000-8000-00000000000'||v.n)::uuid,r.id from (values(1,'operations_lead'),(2,'technical_lead'),(3,'content_community_lead'),(4,'platform_owner'),(5,'technical_lead'))v(n,code)join public.roles r on r.code=v.code;
insert into public.services(id,slug,title,description,status,accepting_requests) values('4b100000-0000-4000-8000-000000000001','project-test','Test','Test','published',true);
insert into business_private.project_requests(id,service_id,service_snapshot,full_name,email,whatsapp,requirements,status,consent_version,idempotency_hash,payload_hash) values('4b200000-0000-4000-8000-000000000001','4b100000-0000-4000-8000-000000000001','{"title":"Test"}','Private client','private-client@example.invalid','+237600000000','Private enquiry payload','approved','test',decode(repeat('4b',32),'hex'),decode(repeat('4c',32),'hex'));
create function pg_temp.claims(n integer,assurance text default 'aal2') returns text language sql as $$select json_build_object('sub','4b000000-0000-4000-8000-00000000000'||n,'role','authenticated','aal',assurance,'session_id','4b000000-0000-4000-8000-00000000000'||n,'exp',extract(epoch from now()+interval '1 hour')::bigint)::text$$;
create temp table targets(label text,id uuid);grant all on targets to authenticated;
select extensions.is((select count(*) from public.permissions),27::bigint,'four explicit project permissions');
select extensions.is((select count(*) from public.role_permissions),52::bigint,'eleven scoped project/overview grants');
select extensions.ok(not has_function_privilege('anon','public.company_project_overview()','execute'),'anonymous overview denied');
select extensions.ok(not has_function_privilege('service_role','public.prepare_project_progress(uuid,integer,uuid,boolean)','execute'),'privileged ingress cannot queue progress');
select extensions.ok(not has_table_privilege('authenticated','business_private.projects','INSERT,UPDATE,DELETE'),'direct project writes denied');
select extensions.ok(not has_table_privilege('authenticated','business_private.project_notification_intents','SELECT'),'raw outbox recipient inaccessible');
set local role authenticated;
select set_config('request.jwt.claims',pg_temp.claims(1),true);
select extensions.throws_ok($$select public.save_staff_project(null,0,'internal',null,'Forbidden','','planned',null,null)$$,'42501',null,'Operations cannot create projects');
select extensions.throws_ok($$select public.release_project_intake('4b200000-0000-4000-8000-000000000001',1,0,'Reviewed scope','Evidence','Agreement',false,true)$$,'22023',null,'release requires independent contact attestation');
select extensions.lives_ok($$select public.release_project_intake('4b200000-0000-4000-8000-000000000001',1,0,'Approved technical scope','Client reply verified independently','Agreement TEST',true,true)$$,'Operations release approved technical scope');
select extensions.throws_ok($$select public.release_project_intake('4b200000-0000-4000-8000-000000000001',1,0,'New scope','Evidence','Agreement',true,true)$$,'PT409',null,'stale release update denied');
select set_config('request.jwt.claims',pg_temp.claims(2,'aal1'),true);
select extensions.throws_ok($$select public.list_staff_projects()$$,'42501',null,'AAL1 project access denied');
select set_config('request.jwt.claims',pg_temp.claims(2),true);
select extensions.ok(public.list_project_intakes()::text not like '%private-client%' and public.list_project_intakes()::text not like '%Private enquiry%','technical intake excludes contact and enquiry');
select extensions.throws_ok($$select public.get_project_intake('4b200000-0000-4000-8000-000000000001')$$,'42501',null,'Technology cannot read verification evidence');
insert into targets select 'internal',(public.save_staff_project(null,0,'internal',null,'Internal research','Internal notes','planned',null,null)->>'id')::uuid;
insert into targets select 'client',(public.save_staff_project(null,0,'client','4b200000-0000-4000-8000-000000000001','Confidential client title','Technical notes','active',null,null)->>'id')::uuid;
select extensions.is(public.get_staff_project((select id from targets where label='internal'))->'progress'->>'percent',null::text,'zero milestones not planned');
select extensions.throws_ok($$select public.save_staff_project(null,0,'client','4b200000-0000-4000-8000-000000000001','Duplicate','','planned',null,null)$$,'PT409',null,'one client project per approved request');
select extensions.throws_ok($$select public.save_staff_project(null,0,'client','4b200000-0000-4000-8000-000000000002','Unknown','','planned',null,null)$$,'22023',null,'unreleased request rejected');
select extensions.throws_ok($$select public.save_staff_project(null,0,'internal','4b200000-0000-4000-8000-000000000001','Wrong linkage','','planned',null,null)$$,'22023',null,'internal cannot carry client linkage');
select extensions.lives_ok($$select public.save_project_milestone((select id from targets where label='client'),1,null,'Private technical milestone','Secret internal notes','The first deliverable is ready.','completed','')$$,'completed milestone saved without automatically preparing mail');
select extensions.is(jsonb_array_length(public.get_staff_project((select id from targets where label='client'))->'notifications'),0,'completion alone creates zero notification intents');
insert into targets select 'milestone',(public.get_staff_project((select id from targets where label='client'))->'milestones'->0->>'id')::uuid;
select extensions.is(public.get_staff_project((select id from targets where label='client'))->'progress'->>'percent','100','one completed milestone is 100%');
select extensions.lives_ok($$select public.save_project_milestone((select id from targets where label='client'),2,null,'Second','','','pending','')$$,'second milestone added');
select extensions.is(public.get_staff_project((select id from targets where label='client'))->'progress'->>'percent','50','equal weighting recalculated');
select extensions.throws_ok($$select public.save_project_milestone((select id from targets where label='client'),2,null,'Stale','','','pending','')$$,'PT409',null,'stale project mutation denied');
select extensions.throws_ok($$select public.reorder_project_milestones((select id from targets where label='client'),3,array[(select id from targets where label='milestone')])$$,'22023',null,'partial ordering rejected');
select extensions.throws_ok($$select public.prepare_project_progress((select id from targets where label='client'),3,(select id from targets where label='milestone'),false)$$,'22023',null,'explicit safe-copy confirmation required');
select extensions.lives_ok($$select public.prepare_project_progress((select id from targets where label='client'),3,(select id from targets where label='milestone'),true)$$,'verified request contact resolved privately for intent');
select extensions.lives_ok($$select public.prepare_project_progress((select id from targets where label='client'),3,(select id from targets where label='milestone'),true)$$,'repeated confirmation idempotent');
select extensions.is(jsonb_array_length(public.get_staff_project((select id from targets where label='client'))->'notifications'),1,'one notification only');
select extensions.ok(public.get_staff_project((select id from targets where label='client'))->'notifications'->0->>'summary'='The first deliverable is ready.','only client-safe wording in notification');
select extensions.ok(public.get_staff_project((select id from targets where label='client'))::text not like '%private-client@example.invalid%','project view does not expose delivery contact');
select extensions.throws_ok($$select public.prepare_project_progress((select id from targets where label='internal'),1,(select id from targets where label='milestone'),true)$$,'22023',null,'internal project never prepares client mail');
select extensions.lives_ok($$select public.save_project_milestone((select id from targets where label='client'),4,(select id from targets where label='milestone'),'Private technical milestone','Secret internal notes','The first deliverable is ready.','pending','')$$,'milestone reopened');
select extensions.is(public.get_staff_project((select id from targets where label='client'))->'progress'->>'percent','0','reopening recalculates progress');
select extensions.lives_ok($$select public.save_project_milestone((select id from targets where label='client'),5,(select id from targets where label='milestone'),'Private technical milestone','Secret internal notes','Updated client text','completed','')$$,'milestone completed again');
select extensions.lives_ok($$select public.prepare_project_progress((select id from targets where label='client'),6,(select id from targets where label='milestone'),true)$$,'recompletion does not create new notice');
select extensions.is(jsonb_array_length(public.get_staff_project((select id from targets where label='client'))->'notifications'),1,'unique initial notice survives reopening');
select extensions.throws_ok($$select public.save_project_milestone((select id from targets where label='internal'),1,(select id from targets where label='milestone'),'Wrong project','','','pending','')$$,'22023',null,'cross-project milestone substitution denied');
select extensions.throws_ok($$select public.save_project_milestone((select id from targets where label='client'),6,(public.get_staff_project((select id from targets where label='client'))->'milestones'->1->>'id')::uuid,'Second','','','excluded','')$$,'22023',null,'exclusion requires audited reason');
select extensions.lives_ok($$select public.save_project_milestone((select id from targets where label='client'),6,(public.get_staff_project((select id from targets where label='client'))->'milestones'->1->>'id')::uuid,'Second','','','excluded','Agreed scope removal')$$,'milestone exclusion explicit');
select extensions.is(public.get_staff_project((select id from targets where label='client'))->'progress'->>'percent','100','excluded milestone removed from denominator');
select extensions.lives_ok($$select public.reorder_project_milestones((select id from targets where label='client'),7,(select array_agg(id order by position desc) from business_private.project_milestones where project_id=(select id from targets where label='client')))$$,'exact full order accepted');
select extensions.throws_ok($$select public.reorder_project_milestones((select id from targets where label='client'),8,array[(select id from targets where label='milestone'),(select id from targets where label='milestone')])$$,'22023',null,'duplicate IDs cannot replace a missing milestone');
reset role;
update business_private.project_requests set email='changed@example.invalid' where id='4b200000-0000-4000-8000-000000000001';
set local role authenticated;select set_config('request.jwt.claims',pg_temp.claims(2),true);
select extensions.throws_ok($$select public.prepare_project_progress((select id from targets where label='client'),8,(select id from targets where label='milestone'),true)$$,'22023',null,'changed request contact cannot inherit verification');
reset role;update business_private.project_requests set email='private-client@example.invalid' where id='4b200000-0000-4000-8000-000000000001';
set local role authenticated;select set_config('request.jwt.claims',jsonb_set(pg_temp.claims(2)::jsonb,'{exp}','0')::text,true);
select extensions.throws_ok($$select public.company_project_overview()$$,'42501',null,'expired assurance denied');
select set_config('request.jwt.claims',pg_temp.claims(3),true);
select extensions.ok(public.company_project_overview()::text not like '%Confidential client title%' and public.company_project_overview()::text not like '%Technical notes%' and public.company_project_overview()::text not like '%4b200000%','shared summary omits client private fields/linkage');
select extensions.throws_ok($$select public.list_staff_projects()$$,'42501',null,'Content cannot read private project details');
select extensions.is((select count(*) from business_private.projects),0::bigint,'direct RLS hides projects from Content');
select set_config('request.jwt.claims',pg_temp.claims(1),true);
select extensions.is(jsonb_array_length(public.list_staff_projects()),2,'Operations read-only visibility');
select extensions.lives_ok($$select public.release_project_intake('4b200000-0000-4000-8000-000000000001',1,1,'','','',false,false)$$,'intake can be revoked without deleting project');
select set_config('request.jwt.claims',pg_temp.claims(2),true);
select extensions.throws_ok($$select public.prepare_project_progress((select id from targets where label='client'),6,(select id from targets where label='milestone'),true)$$,'22023',null,'withdrawn contact release blocks notification preparation');
select set_config('request.jwt.claims',pg_temp.claims(4),true);
select extensions.is(jsonb_array_length(public.list_staff_projects()),2,'Platform Owner project access preserved');
select set_config('request.jwt.claims',pg_temp.claims(5),true);
select extensions.throws_ok($$select public.company_project_overview()$$,'42501',null,'inactive staff denied');
select set_config('request.jwt.claims',pg_temp.claims(6),true);
select extensions.throws_ok($$select public.company_project_overview()$$,'42501',null,'unassigned account denied');
reset role;
select extensions.is((select count(*) from business_private.project_notification_intents where project_id=(select id from targets where label='client')),1::bigint,'one durable notification after retries');
select extensions.is((select count(*) from public.audit_logs where action='project.progress_prepared' and resource_id=(select id::text from targets where label='client')),1::bigint,'one confirmation audit');
select extensions.is((select recipient from business_private.project_notification_intents where project_id=(select id from targets where label='client')),'private-client@example.invalid','recipient is exactly the verified linked request contact');
create function pg_temp.fail_project_audit() returns trigger language plpgsql as $$begin if new.action in ('project.saved','project.progress_prepared') then raise exception 'Synthetic audit rollback';end if;return new;end;$$;
create trigger fail_project_audit before insert on public.audit_logs for each row execute function pg_temp.fail_project_audit();
set local role authenticated;select set_config('request.jwt.claims',pg_temp.claims(2),true);
select extensions.throws_ok($$select public.save_staff_project(null,0,'internal',null,'Must roll back','','planned',null,null)$$,'P0001',null,'audit failure fails operation');
select extensions.is(jsonb_array_length(public.list_staff_projects()),2,'audit failure leaves no partial project');
reset role;update business_private.project_intakes set active=true where request_id='4b200000-0000-4000-8000-000000000001';
set local role authenticated;select set_config('request.jwt.claims',pg_temp.claims(2),true);
select public.save_project_milestone((select id from targets where label='client'),8,null,'Rollback notification','','Reviewed completion','completed','');
insert into targets select 'rollback_milestone',id from business_private.project_milestones where project_id=(select id from targets where label='client') and title='Rollback notification';
select extensions.throws_ok($$select public.prepare_project_progress((select id from targets where label='client'),9,(select id from targets where label='rollback_milestone'),true)$$,'P0001',null,'notification audit failure rolls back intent');
select extensions.is(jsonb_array_length(public.get_staff_project((select id from targets where label='client'))->'notifications'),1,'failed notification creates no partial outbox row');
select extensions.is(public.get_staff_project((select id from targets where label='client'))->>'version','9','failed notification preserves project version');
select set_config('request.jwt.claims',pg_temp.claims(2,'aal1'),true);
select extensions.is((select count(*) from business_private.projects),0::bigint,'direct AAL1 project reads hidden');
reset role;
select * from extensions.finish();rollback;
